function v3_e3_evidence(out)
L=readtable(fullfile(out,'E3/cases/V3_L/cmg_timeseries.csv'));S=readtable(fullfile(out,'E3/cases/V3_S/cmg_timeseries.csv'));Z=readtable(fullfile(out,'E3/cases/V3_Z/cmg_timeseries.csv'));t=L.time_s;fields={'g1','g2','g3','g4'};gL=L{:,fields};gS=interp1(S.time_s,S{:,fields},t);gZ=interp1(Z.time_s,Z{:,fields},t);delta=gL-gZ;f=figure('Visible','off');tiledlayout(3,2);
for k=1:4,nexttile(k);plot(t,rad2deg(delta(:,k)),'Color',[.85 .325 .098],'DisplayName','L - Z');hold on;plot(t,rad2deg(gS(:,k)-gZ(:,k)),'Color',[0 .447 .741],'DisplayName','S - Z');ylabel(sprintf('Delta gamma %d (deg)',k));xline(11.8,'k:','HandleVisibility','off');xline(30,'k--','HandleVisibility','off');xline(35,'k-','HandleVisibility','off');grid on;legend('Location','best');end
nexttile(5);plot(L.time_s,L.sigma_min,'Color',[.85 .325 .098]);hold on;plot(S.time_s,S.sigma_min,'Color',[0 .447 .741]);plot(Z.time_s,Z.sigma_min,'Color',[.35 .35 .35]);ylabel('Actual sigma min');legend('L','S','Z');grid on;xlabel('Time (s)');nexttile(6);plot(t,rad2deg(max(abs(delta),[],2)),'Color',[.85 .325 .098]);ylabel('max |gamma L - Z| (deg)');xline(11.8,'k:');xline(35,'k:');grid on;xlabel('Time (s)');v3_savefig(f,out,'E3_task_relative_configuration');
movement=rad2deg(max(abs(delta),[],2));dt=median(diff(t));n=round(.6/dt);active=movement>2 & t>=11.8 & t<35;run=filter(ones(n,1),1,double(active));k=find(run>=n,1);onset=NaN;if ~isempty(k),onset=t(k-n+1);end
e=struct('role','Secondary task-relative diagnostic; does not replace prespecified absolute 10deg onset','long_earliest_preview_s',11.8,'short_earliest_preview_s',30,'L_minus_Z_max_before_preview_deg',max(movement(t<11.8)),'L_minus_Z_2deg_sustained_600ms_onset_s',onset,'task_advance_from_secondary_diagnostic_s',35-onset);paper_json(fullfile(out,'reports','E3_task_relative_diagnostic.json'),e);
path=fullfile(out,'reports','E3.md');body=fileread(path);point=strfind(body,'### 任务相对构型差');if ~isempty(point),body=body(1:point(1)-1);end;f=fopen(path,'w','n','UTF-8');fprintf(f,'%s',body);c=onCleanup(@()fclose(f));fprintf(f,'\n### 任务相对构型差（辅助诊断）\n\nL−Z在11.8s以前最大框架差 %.6g°；未来任务最早进入长时域11.8s、短时域30s。辅助诊断定义L−Z最大框架差超过2°并持续0.6s，首次时刻 %.4f s。该量不能替代预先规定的10°绝对迁移主指标，也不能把S与L不同网格的所有差异归因于预测性迁移。\n\n![任务相关构型差](../figures/E3_task_relative_configuration.png)\n',e.L_minus_Z_max_before_preview_deg,onset);
end
